package fit.biejk.entity;

import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.MappedSuperclass;
import jakarta.persistence.Version;
import lombok.Getter;
import lombok.Setter;

import java.util.UUID;

/**
 * Base class of the entities: a UUID identifier and a version for optimistic locking.
 */
@Getter
@Setter
@MappedSuperclass
public abstract class BaseEntity {

    /**
     * Unique identifier, generated by the application (UUID v4) when the entity is first saved.
     */
    @Id
    @GeneratedValue(strategy = GenerationType.UUID)
    private UUID id;

    /**
     * Version of the row; a concurrent update of an outdated row fails.
     */
    @Version
    private Long version;
}
